/// Target → everything the frame needs to draw the tab (§9.1).
#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct PageDescriptor {
    pub target: String,
    pub title: String,
    pub icon: String,
    pub kind_label: Option<Label>,
    pub found: bool,
    pub state: NodeState,
    pub state_reason: Option<Label>,
    pub breadcrumb: Vec<Crumb>,
    pub page: PageKind,
    pub view: Vec<ViewNode>,
    /// From the page's manifest declaration, in order (§9.3 "操作区").
    pub actions: Vec<ActionDecl>,
    pub result_tabs: Vec<ResultTabDecl>,
    pub resource_id: Option<String>,
    pub run_id: Option<String>,
    pub uses_env: bool,
    /// Whether the frame shows the information panel (resource pages).
    pub has_info: bool,
    pub read_only: bool,
    /// Re-resolve ~300 ms after bound content stops changing (§9.3).
    pub recompute: bool,
    /// Saved values of the bound fields, by bind path.
    pub values: JsonMap,
    pub autosave: bool,
    /// What `values` is based on; sent back with `page.save` so a change made elsewhere is
    /// detected. Resources: the `rev`. Plugin pages: opaque, from the plugin.
    pub basis: Option<String>,
    /// Round 5 (§6.3): policies in force for this page — `readonly`, `noExport`. Absent = none.
    pub restrictions: Option<Vec<String>>,
}

