/// The single way a page's bound fields are written.
/// - `resource:<id>`: the kernel turns `changes` into one command of the write pipeline (§4).
/// - `new:<kind>?parent=<id>`: creates the resource first (§9.1); the result carries the new target.
/// - `node:` / `page:` targets: the owning plugin's page handler `save(ctx, changes)` decides.
#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct PageSaveParams {
    pub target: String,
    /// Bind path → new value; only what changed.
    pub changes: JsonMap,
    pub basis: Option<String>,
    pub context: Option<PageContext>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct PageSaveResult {
    /// The page as it is after saving; `page.target` differs from the request for `new:` targets.
    pub page: PageDescriptor,
}

