/// What the shell should do after a command ran, or when a plugin asks through `host.ui`.
#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "kebab-case", rename_all_fields = "camelCase")]
#[ts(export, optional_fields)]
pub enum CommandEffect {
    Open {
        target: String,
        /// Initial page state for the opened tab (§9.1, D292), e.g. a run's parameters.
        params: Option<BTreeMap<String, String>>,
        env_id: Option<String>,
    },
    Toast { message: Label, tone: Option<ToastTone> },
    /// Start inline rename of this node.
    Rename { tree: String, key: String },
    Reveal { tree: String, key: String },
    CloseTarget { target: String },
    /// Ask the user for a folder with the system dialog, then call `plugin.grantFolder`.
    /// The choice in the dialog is the user's consent (D184).
    PickFolder { plugin: String },
    /// Ask for confirmation, then execute `command` again with `args.confirmed = true`.
    Confirm { message: Label, command: String, danger: Option<bool> },
    /// Copy text to the clipboard.
    Copy { text: String },
    Reload,
}

