#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn wire_shapes_are_stable() {
        let node = ViewNode::Form {
            id: "f".into(),
            layout: FormLayout::Stack,
            label: None,
            fields: vec![ViewField {
                name: "text".into(),
                label: Label::Text("Text".into()),
                kind: FieldKind::Longtext,
                bind: Some("body.text".into()),
                param: None,
                options: None,
                presets: None,
                fill: Some(true),
                language: None,
                hint: None,
                placeholder: None,
                env_value: None,
                env_source: None,
                read_only: None,
            }],
        };
        assert_eq!(
            serde_json::to_value(&node).unwrap(),
            json!({ "type": "form", "id": "f", "layout": "stack",
                    "fields": [{ "name": "text", "label": "Text", "kind": "longtext", "bind": "body.text", "fill": true }] })
        );
        let effect = CommandEffect::PickFolder { plugin: "p".into() };
        assert_eq!(serde_json::to_value(&effect).unwrap(), json!({ "type": "pick-folder", "plugin": "p" }));
        assert_eq!(serde_json::to_value(NodeState::MissingPlugin).unwrap(), json!("missing-plugin"));
        assert_eq!(serde_json::to_value(ErrorCode::WorkerGone).unwrap(), json!("workerGone"));
        let label: Label = serde_json::from_value(json!({ "en-US": "Note", "zh-CN": "笔记" })).unwrap();
        assert!(matches!(label, Label::Localized(_)));
    }

    #[test]
    fn plugin_views_with_unknown_fields_are_rejected() {
        let bad = json!({ "type": "text", "id": "t", "text": "x", "style": "color:red" });
        assert!(serde_json::from_value::<ViewNode>(bad).is_err());
        let unknown = json!({ "type": "iframe", "id": "t" });
        assert!(serde_json::from_value::<ViewNode>(unknown).is_err());
    }

    #[test]
    fn request_without_params_or_client_parses() {
        let r: Request = serde_json::from_str(r#"{"id":1,"method":"tree.list"}"#).unwrap();
        assert!(r.params.is_null() && r.client.is_none());
    }
}
